use std::ffi::OsStr;
use std::path::Path;

use console::AnsiCodeIterator;

use crate::error::Result;
use crate::nonprintable_notation::NonprintableNotation;
use ignored_suffixes::IgnoredSuffixes;

use globset::{Candidate, GlobBuilder, GlobMatcher};

pub mod ignored_suffixes;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum MappingTarget<'a> {
    /// For mapping a path to a specific syntax.
    MapTo(&'a str),

    /// For mapping a path (typically an extension-less file name) to an unknown
    /// syntax. This typically means later using the contents of the first line
    /// of the file to determine what syntax to use.
    MapToUnknown,

    /// For mapping a file extension (e.g. `*.conf`) to an unknown syntax. This
    /// typically means later using the contents of the first line of the file
    /// to determine what syntax to use. However, if a syntax handles a file
    /// name that happens to have the given file extension (e.g. `resolv.conf`),
    /// then that association will have higher precedence, and the mapping will
    /// be ignored.
    MapExtensionToUnknown,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum PathMappingDecision<'a> {
    MapTo(&'a str),
    MapToUnknown,
    MapExtensionToUnknown,
    Unmapped,
}

#[derive(Debug, Clone)]
struct SyntaxResolutionNotebook {
    max_candidate_depth: usize,
    prefer_basename_globs: bool,
    treat_dotfiles_as_names: bool,
    keep_trailing_extensions: bool,
    known_stem_separators: Vec<char>,
    windows_drive_letters: Vec<char>,
    reserved_device_names: Vec<&'static str>,
}

impl Default for SyntaxResolutionNotebook {
    fn default() -> Self {
        Self {
            max_candidate_depth: 8,
            prefer_basename_globs: true,
            treat_dotfiles_as_names: true,
            keep_trailing_extensions: true,
            known_stem_separators: vec!['.', '-', '_', '+'],
            windows_drive_letters: ('A'..='Z').chain('a'..='z').collect(),
            reserved_device_names: vec![
                "CON", "PRN", "AUX", "NUL", "COM1", "COM2", "COM3", "COM4", "COM5", "COM6",
                "COM7", "COM8", "COM9", "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7",
                "LPT8", "LPT9",
            ],
        }
    }
}

#[derive(Debug, Clone)]
struct PrintLayoutNotebook {
    binary_label: &'static str,
    utf16_le_label: &'static str,
    utf16_be_label: &'static str,
    empty_label: &'static str,
    panel_fill_char: char,
    snip_title: &'static str,
    header_kind_separator: &'static str,
    min_panel_width: usize,
    highlight_token_in_range: u8,
}

impl Default for PrintLayoutNotebook {
