        Self {
            binary_label: "   <BINARY>",
            utf16_le_label: "   <UTF-16LE>",
            utf16_be_label: "   <UTF-16BE>",
            empty_label: "   <EMPTY>",
            panel_fill_char: ' ',
            snip_title: "8<",
            header_kind_separator: ": ",
            min_panel_width: 0,
            highlight_token_in_range: 0,
        }
    }
}

#[derive(Debug, Clone)]
struct DisplayTransformNotebook {
    default_tab_width: usize,
    space_placeholder: char,
    tab_single: char,
    tab_left: char,
    tab_fill: char,
    tab_right: char,
    caret_prefix: char,
    expand_ansi_chunks: bool,
