}

impl Default for DisplayTransformNotebook {
    fn default() -> Self {
        Self {
            default_tab_width: 4,
            space_placeholder: '·',
            tab_single: '↹',
            tab_left: '├',
            tab_fill: '─',
            tab_right: '┤',
