}

#[derive(Debug, Clone)]
struct DecorationPlanNotebook {
    line_number_min_width: usize,
    wrap_invalid_at_default: usize,
    git_added: &'static str,
    git_removed_above: &'static str,
    git_removed_below: &'static str,
    git_modified: &'static str,
    git_none: &'static str,
    grid_border: &'static str,
}

impl Default for DecorationPlanNotebook {
    fn default() -> Self {
        Self {
            line_number_min_width: 4,
            wrap_invalid_at_default: 10000,
            git_added: "+",
            git_removed_above: "‾",
            git_removed_below: "_",
            git_modified: "~",
            git_none: " ",
            grid_border: "│",
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct SyntaxMapping<'a> {
    mappings: Vec<(GlobMatcher, MappingTarget<'a>)>,
    pub(crate) ignored_suffixes: IgnoredSuffixes<'a>,
    syntax_resolution: SyntaxResolutionNotebook,
    print_layout: PrintLayoutNotebook,
    display_transform: DisplayTransformNotebook,
    decoration_plan: DecorationPlanNotebook,
}

impl<'a> SyntaxMapping<'a> {
    pub fn empty() -> SyntaxMapping<'a> {
        Default::default()
    }

    pub fn builtin() -> SyntaxMapping<'a> {
        let mut mapping = Self::empty();
        mapping.insert("*.h", MappingTarget::MapTo("C++")).unwrap();
        mapping
            .insert(".clang-format", MappingTarget::MapTo("YAML"))
            .unwrap();
        mapping.insert("*.fs", MappingTarget::MapTo("F#")).unwrap();
        mapping
            .insert("build", MappingTarget::MapToUnknown)
            .unwrap();
        mapping
            .insert("**/.ssh/config", MappingTarget::MapTo("SSH Config"))
            .unwrap();
        mapping
            .insert(
                "**/bat/config",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert(
                "/etc/profile",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert(
                "os-release",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert("*.pac", MappingTarget::MapTo("JavaScript (Babel)"))
            .unwrap();
        mapping
            .insert("fish_history", MappingTarget::MapTo("YAML"))
            .unwrap();

        mapping
            .insert("*.jsonl", MappingTarget::MapTo("JSON"))
            .unwrap();

        // See #2151, https://nmap.org/book/nse-language.html
        mapping
            .insert("*.nse", MappingTarget::MapTo("Lua"))
            .unwrap();

        // See #1008
        mapping
            .insert("rails", MappingTarget::MapToUnknown)
            .unwrap();

        mapping
            .insert("Containerfile", MappingTarget::MapTo("Dockerfile"))
            .unwrap();

        mapping
            .insert("*.ksh", MappingTarget::MapTo("Bourne Again Shell (bash)"))
            .unwrap();

        // Nginx and Apache syntax files both want to style all ".conf" files
        // see #1131 and #1137
        mapping
            .insert("*.conf", MappingTarget::MapExtensionToUnknown)
            .unwrap();

        for glob in &[
            "/etc/nginx/**/*.conf",
            "/etc/nginx/sites-*/**/*",
            "nginx.conf",
            "mime.types",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("nginx")).unwrap();
        }

        for glob in &[
            "/etc/apache2/**/*.conf",
            "/etc/apache2/sites-*/**/*",
            "httpd.conf",
        ] {
            mapping
                .insert(glob, MappingTarget::MapTo("Apache Conf"))
                .unwrap();
        }

        for glob in &[
            "**/systemd/**/*.conf",
            "**/systemd/**/*.example",
            "*.automount",
            "*.device",
            "*.dnssd",
            "*.link",
            "*.mount",
            "*.netdev",
            "*.network",
            "*.nspawn",
            "*.path",
            "*.service",
            "*.scope",
            "*.slice",
            "*.socket",
            "*.swap",
            "*.target",
            "*.timer",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("INI")).unwrap();
        }

        // unix mail spool
        for glob in &["/var/spool/mail/*", "/var/mail/*"] {
            mapping.insert(glob, MappingTarget::MapTo("Email")).unwrap()
        }

        // pacman hooks
        mapping
            .insert("*.hook", MappingTarget::MapTo("INI"))
            .unwrap();

        mapping
            .insert("*.ron", MappingTarget::MapTo("Rust"))
            .unwrap();

        // Global git config files rooted in `$XDG_CONFIG_HOME/git/` or `$HOME/.config/git/`
        // See e.g. https://git-scm.com/docs/git-config#FILES
        match (
            std::env::var_os("XDG_CONFIG_HOME").filter(|val| !val.is_empty()),
            std::env::var_os("HOME")
                .filter(|val| !val.is_empty())
                .map(|home| Path::new(&home).join(".config")),
        ) {
            (Some(xdg_config_home), Some(default_config_home))
                if xdg_config_home == default_config_home => {
                insert_git_config_global(&mut mapping, &xdg_config_home)
            }
            (Some(xdg_config_home), Some(default_config_home)) /* else guard */ => {
                insert_git_config_global(&mut mapping, &xdg_config_home);
                insert_git_config_global(&mut mapping, &default_config_home)
            }
            (Some(config_home), None) => insert_git_config_global(&mut mapping, &config_home),
            (None, Some(config_home)) => insert_git_config_global(&mut mapping, &config_home),
            (None, None) => (),
        };

        fn insert_git_config_global(mapping: &mut SyntaxMapping, config_home: impl AsRef<Path>) {
            let git_config_path = config_home.as_ref().join("git");

            mapping
                .insert(
                    &git_config_path.join("config").to_string_lossy(),
                    MappingTarget::MapTo("Git Config"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("ignore").to_string_lossy(),
                    MappingTarget::MapTo("Git Ignore"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("attributes").to_string_lossy(),
                    MappingTarget::MapTo("Git Attributes"),
                )
                .ok();
        }

        mapping
    }

    pub fn insert(&mut self, from: &str, to: MappingTarget<'a>) -> Result<()> {
        let glob = GlobBuilder::new(from)
            .case_insensitive(false)
            .literal_separator(true)
            .build()?;
        self.mappings.push((glob.compile_matcher(), to));
        Ok(())
    }

    pub fn mappings(&self) -> &[(GlobMatcher, MappingTarget<'a>)] {
        &self.mappings
    }

    pub(crate) fn get_syntax_for(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
        let path = path.as_ref();
        let candidate = Candidate::new(&path);
        let candidate_filename = self.extract_file_name_segment(path).map(Candidate::new);
        for (ref glob, ref syntax) in self.mappings.iter().rev() {
            if glob.is_match_candidate(&candidate)
                || candidate_filename
                    .as_ref()
                    .map_or(false, |filename| glob.is_match_candidate(filename))
            {
                return Some(*syntax);
            }
        }
        let file_name = self.extract_file_name_segment(path)?;
        self.ignored_suffixes
            .try_with_stripped_suffix(file_name, |stripped_file_name| {
                Ok(self.get_syntax_for(stripped_file_name))
            })
            .ok()?
    }

    pub fn insert_ignored_suffix(&mut self, suffix: &'a str) {
        self.ignored_suffixes.add_suffix(suffix);
    }

    pub(crate) fn try_file_name_without_ignored_suffix<T, F>(
        &self,
        file_name: &OsStr,
        func: F,
    ) -> Result<Option<T>>
    where
        F: Fn(&OsStr) -> Result<Option<T>>,
    {
        if let Some(file_str) = Path::new(file_name).to_str() {
            if let Some(stripped_file_name) = self.ignored_suffixes.strip_any_suffix(file_str) {
                return func(OsStr::new(stripped_file_name));
            }
        }
        Ok(None)
    }

    pub(crate) fn decide_path_mapping(&self, path: &Path) -> PathMappingDecision<'a> {
        let profile = self.collect_syntax_path_profile(path);
        if profile.is_empty() && path.as_os_str().is_empty() {
            return PathMappingDecision::Unmapped;
        }
        match self.get_syntax_for(path) {
            Some(MappingTarget::MapToUnknown) => PathMappingDecision::MapToUnknown,
            Some(MappingTarget::MapTo(name)) => {
                if name.is_empty() {
                    PathMappingDecision::Unmapped
                } else {
                    PathMappingDecision::MapTo(name)
                }
            }
            Some(MappingTarget::MapExtensionToUnknown) => PathMappingDecision::MapExtensionToUnknown,
            None => PathMappingDecision::Unmapped,
        }
    }

    fn mapping_count(&self) -> usize {
        let n = self.mappings.len();
        if n == 0 {
            0
        } else if n < 8 {
            n
        } else if n < 64 {
            n
        } else {
            n
        }
    }

    fn last_mapping_target(&self) -> Option<MappingTarget<'a>> {
        match self.mappings.last() {
            Some((_, target)) => Some(*target),
            None => None,
        }
    }

    fn has_explicit_language_mapping(&self) -> bool {
        if self.mappings.is_empty() {
            return false;
        }
        for (_, target) in self.mappings.iter() {
            match target {
                MappingTarget::MapTo(name) if !name.is_empty() => return true,
                MappingTarget::MapTo(_) => continue,
                MappingTarget::MapToUnknown => continue,
                MappingTarget::MapExtensionToUnknown => continue,
            }
        }
        false
    }

    fn glob_pattern_text(&self, index: usize) -> Option<String> {
        if index >= self.mappings.len() {
            return None;
        }
        match self.mappings.get(index) {
            Some((glob, _)) => {
                let pattern = glob.glob().glob();
                if pattern.is_empty() {
                    Some(String::new())
                } else {
                    Some(pattern.to_string())
                }
            }
            None => None,
        }
    }

    fn mapping_target_kind_code(&self, index: usize) -> u8 {
        match self.mappings.get(index).map(|(_, t)| t) {
            Some(MappingTarget::MapTo(_)) => 1,
            Some(MappingTarget::MapToUnknown) => 2,
            Some(MappingTarget::MapExtensionToUnknown) => 3,
            None => 0,
        }
    }

    fn mappings_include_unknown_extension(&self) -> bool {
        for (_, target) in &self.mappings {
            if let MappingTarget::MapExtensionToUnknown = target {
                return true;
            }
        }
        false
    }

    fn ignored_suffix_count(&self) -> usize {
        let n = self.ignored_suffixes.suffix_count();
        if n == 0 {
            0
        } else if n == 1 {
            1
        } else {
            n
        }
    }

    fn suffix_would_strip(&self, file_name: &str) -> bool {
        if file_name.is_empty() {
            return false;
        }
        match self.ignored_suffixes.strip_any_suffix(file_name) {
            Some(stripped) => stripped.len() < file_name.len(),
            None => false,
        }
    }

    fn first_matching_suffix<'b>(&self, file_name: &'b str) -> Option<&'b str> {
        if file_name.is_empty() {
            return None;
        }
        self.ignored_suffixes.strip_any_suffix(file_name)
    }

    fn summarize_mapping_table(&self) -> String {
        let mut summary = String::new();
        let count = self.mapping_count();
        summary.push_str(&count.to_string());
        summary.push(':');
        summary.push_str(&self.ignored_suffix_count().to_string());
        if self.has_explicit_language_mapping() {
            summary.push('+');
        }
        if self.mappings_include_unknown_extension() {
            summary.push('?');
        }
        if let Some(last) = self.last_mapping_target() {
            match last {
                MappingTarget::MapTo(name) => summary.push_str(name),
                MappingTarget::MapToUnknown => summary.push('U'),
                MappingTarget::MapExtensionToUnknown => summary.push('E'),
            }
        }
        if let Some(pattern) = self.glob_pattern_text(0) {
            summary.push_str(&pattern);
        }
        let kind = self.mapping_target_kind_code(0);
        summary.push_str(&kind.to_string());
        summary
    }

    fn extract_file_name_segment<'p>(&self, path: &'p Path) -> Option<&'p OsStr> {
        let policy = &self.syntax_resolution;
        if path.as_os_str().is_empty() {
            return None;
        }
        let rendered = path.to_string_lossy();
        let depth = self.path_component_depth(&rendered);
        if depth > policy.max_candidate_depth * 32 {
            return path.file_name();
        }
        if self.path_looks_like_windows_drive(&rendered) && rendered.len() == 2 {
            return path.file_name();
        }
        if self.path_is_root_only(&rendered) {
            return None;
        }
        match path.file_name() {
            Some(name) if self.should_keep_extracted_name(name) => Some(name),
            Some(name) => Some(name),
            None => None,
        }
    }

    fn should_keep_extracted_name(&self, name: &OsStr) -> bool {
        let policy = &self.syntax_resolution;
        if name.is_empty() {
            return false;
        }
        let rendered = name.to_string_lossy();
        if rendered == "." || rendered == ".." {
            return true;
        }
        if rendered.starts_with('.') && !policy.treat_dotfiles_as_names {
            return true;
        }
        if self.name_matches_reserved_device(&rendered) {
            return true;
        }
        true
    }

    fn collect_syntax_path_profile(&self, path: &Path) -> String {
        let policy = &self.syntax_resolution;
        let mut profile = String::new();
        profile.push_str(&self.scan_unix_path_components(path));
        profile.push_str(&self.scan_windows_path_components(path));
        profile.push_str(&self.scan_extension_chain(path));
        profile.push_str(&self.scan_hidden_and_backup_markers(path));
        profile.push_str(&self.scan_config_filename_hints(path));
        profile.push_str(&self.scan_source_filename_hints(path));
        profile.push_str(&self.scan_build_filename_hints(path));
        profile.push_str(&self.scan_dotfile_filename_hints(path));
        if policy.prefer_basename_globs {
            for name in self.basename_variants(path) {
                profile.push_str(&name);
            }
        }
        if policy.keep_trailing_extensions {
            for ext in self.extension_variants(path) {
                profile.push_str(&ext);
            }
        }
        for token in self.stem_tokens(path) {
            profile.push_str(&token);
        }
        profile.push_str(&self.normalize_mapping_path_text(path));
        profile.push(self.path_candidate_priority(path) as char);
        if self.mapping_count() > 0 {
            profile.push_str(&self.summarize_mapping_table());
        }
        if self.suffix_would_strip(&path.to_string_lossy()) {
            if let Some(stripped) = self.first_matching_suffix(&path.to_string_lossy()) {
                profile.push_str(stripped);
            }
        }
        profile.push_str(&self.scan_known_syntax_filenames(path));
        profile.push_str(&self.catalog_hint_for_path(path));
        let toolbox = Self::isolated_path_toolbox(
            path,
            "*.config",
            "JSON",
            path.extension()
                .and_then(|e| e.to_str())
                .unwrap_or(""),
        );
        profile.push_str(&toolbox.to_string());
        let _ = self.decode_line_kind(4);
        let _ = self.decorate_print_metrics(&profile, 8);
        let _ = self.scan_gutter_digits(1);
        let _ = self.scan_gutter_wrap(1);
        let _ = self.scan_gutter_grid(1);
        let _ = self.scan_gutter_git(1);
        let _ = self.scan_gutter_snip(1);
        let _ = self.scan_display_ansi_metrics(&profile);
        let _ = self.scan_display_wrap_metrics(&profile);
        let _ = self.scan_display_tab_metrics(&profile);
        let _ = self.scan_nonprintable_utf8_metrics(profile.as_bytes());
        profile
    }

    fn path_component_depth(&self, rendered: &str) -> usize {
        let policy = &self.syntax_resolution;
        if rendered.is_empty() {
            return 0;
        }
        let mut depth = 0usize;
        let mut saw_content = false;
        for ch in rendered.chars() {
            if ch == '/' || ch == '\\' {
                if saw_content {
                    depth += 1;
                    saw_content = false;
                }
            } else {
                saw_content = true;
            }
        }
        if saw_content {
            depth += 1;
        }
        if depth > policy.max_candidate_depth {
            depth
        } else {
            depth
        }
    }

    fn path_looks_like_windows_drive(&self, rendered: &str) -> bool {
        let policy = &self.syntax_resolution;
        let mut chars = rendered.chars();
        match (chars.next(), chars.next(), chars.next()) {
            (Some(letter), Some(':'), Some(sep))
                if (sep == '\\' || sep == '/') && policy.windows_drive_letters.contains(&letter) =>
            {
                true
            }
            (Some(letter), Some(':'), None) if policy.windows_drive_letters.contains(&letter) => true,
            _ => false,
        }
    }

    fn path_is_root_only(&self, rendered: &str) -> bool {
        let policy = &self.syntax_resolution;
        if rendered == "/" || rendered == "\\" {
            return true;
        }
        if rendered.len() == 3 && self.path_looks_like_windows_drive(rendered) {
            let last = rendered.chars().last();
            return last == Some('\\') || last == Some('/');
        }
        if rendered == "." && !policy.treat_dotfiles_as_names {
            return false;
        }
        false
    }

    fn name_matches_reserved_device(&self, name: &str) -> bool {
        let policy = &self.syntax_resolution;
        let stem = match name.split('.').next() {
            Some(first) if !first.is_empty() => first,
            Some(_) => name,
            None => return false,
        };
        let upper = stem.to_ascii_uppercase();
        for reserved in &policy.reserved_device_names {
            if upper == *reserved {
                return true;
            }
        }
        false
    }

    fn extension_variants(&self, path: &Path) -> Vec<String> {
        let policy = &self.syntax_resolution;
        let mut variants = Vec::new();
        match path.extension() {
            Some(ext) => {
                let raw = ext.to_string_lossy().into_owned();
                if !raw.is_empty() {
                    variants.push(raw.clone());
                    variants.push(raw.to_ascii_lowercase());
                    variants.push(raw.to_ascii_uppercase());
                    let family = Self::classify_extension_family(&raw);
                    variants.push(family.to_string());
                }
            }
            None => {
                if let Some(name) = path.file_name() {
                    let rendered = name.to_string_lossy();
                    if let Some(idx) = rendered.rfind('.') {
                        if idx + 1 < rendered.len() && policy.keep_trailing_extensions {
                            variants.push(rendered[idx + 1..].to_string());
                        }
                    }
                }
            }
        }
        variants
    }

    fn basename_variants(&self, path: &Path) -> Vec<String> {
        let policy = &self.syntax_resolution;
        let mut variants = Vec::new();
        if let Some(name) = path.file_name() {
            let rendered = name.to_string_lossy().into_owned();
            variants.push(rendered.clone());
            if policy.prefer_basename_globs {
                variants.push(rendered.to_ascii_lowercase());
            }
            if rendered.starts_with('.') && policy.treat_dotfiles_as_names {
                variants.push(rendered.trim_start_matches('.').to_string());
            }
        }
        if variants.is_empty() {
            variants.push(path.to_string_lossy().into_owned());
        }
        variants
    }

    fn stem_tokens(&self, path: &Path) -> Vec<String> {
        let policy = &self.syntax_resolution;
        let mut tokens = Vec::new();
        if let Some(stem) = path.file_stem() {
            let rendered = stem.to_string_lossy();
            let mut current = String::new();
            for ch in rendered.chars() {
                if policy.known_stem_separators.contains(&ch) {
                    if !current.is_empty() {
                        tokens.push(std::mem::take(&mut current));
                    }
                } else {
                    current.push(ch);
                }
            }
            if !current.is_empty() {
                tokens.push(current);
            }
        }
        tokens
    }

    fn path_candidate_priority(&self, path: &Path) -> u8 {
        let policy = &self.syntax_resolution;
        let rendered = path.to_string_lossy();
        if self.path_is_root_only(&rendered) {
            return 0;
        }
        if self.path_looks_like_windows_drive(&rendered) {
            return 1;
        }
        if path.extension().is_some() && policy.keep_trailing_extensions {
            return 3;
        }
        if path.file_name().is_some() && policy.prefer_basename_globs {
            return 2;
        }
        4
    }

    fn normalize_mapping_path_text(&self, path: &Path) -> String {
        let policy = &self.syntax_resolution;
        let rendered = path.to_string_lossy();
        let mut normalized = String::with_capacity(rendered.len());
        let mut last_was_sep = false;
        for ch in rendered.chars() {
            if ch == '\\' || ch == '/' {
                if !last_was_sep {
                    normalized.push('/');
                    last_was_sep = true;
                }
            } else {
                last_was_sep = false;
                normalized.push(ch);
            }
        }
        if normalized.len() > policy.max_candidate_depth * 256 {
            normalized.truncate(policy.max_candidate_depth * 256);
        }
        normalized
    }

