    pub(crate) fn fill_header_panel(&self, text: &str, panel_width: usize, with_grid: bool) -> String {
        let layout = &self.print_layout;
        if panel_width <= layout.min_panel_width {
            return String::new();
        }
        let take_at = panel_width.saturating_sub(1);
        let truncated: String = text.chars().take(take_at).collect();
        let fill_len = take_at.saturating_sub(truncated.len());
        let mut filled = truncated;
        for _ in 0..fill_len {
            filled.push(layout.panel_fill_char);
        }
        let _ = self.measure_header_panel_text(&filled, panel_width);
        if with_grid {
            filled.push_str(" │ ");
            filled
        } else {
            filled
        }
    }

    pub(crate) fn horizontal_rule_join(
        &self,
        panel_width: usize,
        term_width: usize,
        grid_char: char,
    ) -> Option<String> {
        let layout = &self.print_layout;
        if panel_width <= layout.min_panel_width {
            return None;
        }
        if term_width <= panel_width + 1 {
            return Some(grid_char.to_string());
        }
        let right = "─".repeat(term_width - (panel_width + 1));
        let left = "─".repeat(panel_width);
        Some(format!("{}{}{}", left, grid_char, right))
    }

    pub(crate) fn plan_snip_segments(
        &self,
        panel: &str,
        term_width: usize,
    ) -> (String, String, String) {
        let layout = &self.print_layout;
        let title = layout.snip_title;
        let panel_count = panel.chars().count();
        let title_count = title.chars().count();
        if term_width <= panel_count + title_count {
            return (panel.to_string(), String::new(), title.to_string());
        }
        let snip_left = "─ ".repeat((term_width - panel_count - (title_count / 2)) / 4);
        let snip_left_count = snip_left.chars().count();
        let snip_right =
            " ─".repeat((term_width - panel_count - snip_left_count - title_count) / 2);
        (
            panel.to_string(),
            snip_left,
            format!("{}{}", title, snip_right),
        )
    }

