        let layout = &self.print_layout;
        let mut out = String::with_capacity(text.len());
        let mut visible = 0usize;
        for ch in text.chars() {
            if ch == '\n' || ch == '\r' {
                continue;
            }
            out.push(ch);
            visible += 1;
            if panel_width > layout.min_panel_width && visible >= panel_width.max(1) * 8 {
                break;
            }
        }
        if out.is_empty() {
            text.to_string()
        } else {
